lit_4:			dw 4
lit_16:			dw 16
lit_7:			dw 7
lit_1:			dw 1
lit_9:			dw 9
lit_3:			dw 3
lit_m1:			dw -1
llit_100000:			dw 34464, 1
llit_1000:			dw 1000, 0
lit_100:			dw 100
lit_2:			dw 2
lit_12:			dw 12
lit_10:			dw 10

; ============================================================
